@app.route('/get_name') 
def get_name(): 
     # Get the 'name' parameter from the URL 
     name = request.args.get('name') 

     # Check if the 'name' parameter is provided 
     if not name: 
         return "Parameter 'name' is missing from the URL" 

     # Construct the file path 
     file_path = os.path.join('names', name) 

     try: 
         # Open the file with the specified name 
         with open(file_path, 'r') as file: 
             # Read the content of the file or perform any desired operations 
             file_content = file.read() 
         return file_content 
     except FileNotFoundError: 
         return f"File '{name}' not found" 
     except Exception as e: 
         return f"An error occurred: {str(e)}"

def decode_and_send_payload(jwt_token, secret_key): 
     try: 
         # Decode the JWT token using the secret key 
         decoded_payload = jwt.decode(jwt_token, secret_key, algorithms=['HS256']) 

         # Send the decoded payload (you can customize this part) 
         print("Decoded JWT Payload:") 
         for key, value in decoded_payload.items(): 
             print(f"{key}: {value}") 

         return decoded_payload 
     except jwt.ExpiredSignatureError: 
         return "Token has expired" 
     except jwt.InvalidTokenError: 
         return "Invalid token" 
     except Exception as e: 
         return f"Error decoding token: {e}"

def sign_token(secret_key, token): # Convert the key and token to bytes key = urlsafe_b64decode(secret_key) token_bytes = token.encode('utf-8')
# Sign the token using HMAC-SHA256 h = hmac.HMAC(key, hashes.SHA256(), backend=default_backend()) h.update(token_bytes) signature = h.finalize()
# Return the base64-encoded signature return urlsafe_b64encode(signature).decode('utf-8')

def hash_to_bucket(key, num_buckets): # Calculate the hash value using the built-in hash function hash_value = hash(key)
# Map the hash value to a non-negative integer within the range of num_buckets bucket_index = hash_value % num_buckets
return bucket_index

