unit.function:
def create_token(username):
     # Set the payload, including the username
     payload = {
         'username': username,
         'exp': datetime.datetime.utcnow() + datetime.timedelta(days=1)  # Token expiration time
     }

     # Encode the token
     token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
     return token

def decode_token(token):
     try:
         # Decode the token
         decoded_payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
         return decoded_payload['username']
     except jwt.ExpiredSignatureError:
         return "Token has expired."
     except jwt.InvalidTokenError:
         return "Invalid token."

@app.route('/delete-ingredient/<int:ingredient_id>', methods=['DELETE'])
def delete_ingredient(ingredient_id):
     global ingredients

     # Find the index of the ingredient with the given ID
     index_to_delete = None
     for i, ingredient in enumerate(ingredients):
         if ingredient['id'] == ingredient_id:
             index_to_delete = i
             break

     # If ingredient with the given ID is found, delete it
     if index_to_delete is not None:
         deleted_ingredient = ingredients.pop(index_to_delete)
         return jsonify({'message': f'Ingredient with ID {ingredient_id} deleted successfully', 'deleted_ingredient': deleted_ingredient})
     else:
         return jsonify({'message': f'Ingredient with ID {ingredient_id} not found'}), 404

def start_server(): # Set the server address and port server_address = ('localhost', 8080)
# Create a TCP/IP socket server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM) server_socket.bind(server_address) server_socket.listen(1)
# Create an SSL context with or without client certificate validation ssl_context = create_ssl_context(validate_cert=True)
print("Server is listening for incoming connections...")
while True: client_socket, client_address = server_socket.accept()
# Wrap the socket with the SSL context ssl_socket = ssl_context.wrap_socket(client_socket, server_side=True)
try: # Your server logic goes here # For example, receive data from the client data = ssl_socket.recv(1024) print(f"Received data from client: {data.decode()}")
finally: # Close the SSL socket ssl_socket.close()

