class MyHandler(xml.sax.ContentHandler): 
     def __init__(self): 
         self.current_element = "" 
         self.result = "" 

     def startElement(self, name, attrs): 
         self.current_element = name 

     def endElement(self, name): 
         self.current_element = "" 

     def characters(self, content): 
         if self.current_element == "data": 
             self.result += content

