def GetRoot(xml_string): 
     try: 
         # Create an ElementTree from the XML string 
         tree = ET.ElementTree(ET.fromstring(xml_string)) 

         # Get the root element of the tree 
         root = tree.getroot() 

         return root 

     except ET.ParseError as e: 
         print(f"XML parse error: {e}") 
         return None

def root(xml_file): 
     try: 
         # Create an ElementTree from the XML file 
         tree = ET.parse(xml_file) 

         # Get the root element of the tree 
         root_element = tree.getroot() 

         return root_element 

     except ET.ParseError as e: 
         print(f"XML parse error: {e}") 
         return None

def parse_xml_from_file(xml_file): 
     try: 
         # Create an ElementTree from the XML file 
         tree = ET.parse(xml_file) 

         # Get the root element of the tree 
         root_element = tree.getroot() 

         return root_element 

     except ET.ParseError as e: 
         print(f"XML parse error: {e}") 
         return None

unit.class:
class CustomRequestHandler(SimpleHTTPRequestHandler): 
     # Restrict access by overriding the do_GET method 
     def do_GET(self): 
         # Allow access only from localhost (127.0.0.1) 
         if self.client_address[0] == "127.0.0.1": 
             super().do_GET() 
         else: 
             self.send_response(403) 
             self.end_headers() 
             self.wfile.write(b"Access denied")

